import{_ as p,a0 as l,w as o,s as d,ao as r,I as i,x as n,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"使用 Linux 的 ping 命令診斷網絡連接問題 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux 的 ping 命令診斷網絡連接問題 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux 的 ping 命令診斷網絡連接問題 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux 的 ping 命令診斷網絡連接問題 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20211020 Diagnose connectivity issues with the Linux ping command","title":"使用 Linux 的 ping 命令診斷網絡連接問題","tag":"202211","desc":""},"relativePath":"202211/20211020 Diagnose connectivity issues with the Linux ping command.md","filePath":"[post].md"}'),g={name:"202211/20211020 Diagnose connectivity issues with the Linux ping command.md"};function c(h,s,u,b,m,k){const e=l("Link");return o(),d("div",null,[s[33]||(s[33]=r(`<h1 id="使用-linux-的-ping-命令診斷網絡連接問題" tabindex="-1">使用 Linux 的 ping 命令診斷網絡連接問題 <a class="header-anchor" href="#使用-linux-的-ping-命令診斷網絡連接問題" aria-label="Permalink to “使用 Linux 的 ping 命令診斷網絡連接問題”">​</a></h1><blockquote><p>在本文中，我們將討論網絡連接最基本的診斷工具之一：<code>ping</code> 命令。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202211/20/094045mhhkqhepke4qebks.jpg" alt=""></p><p>如今，聯網計算機變得十分普遍，以至於我們大多數人都理所當然地認為，房間一側的計算機可以連接上房間另一側的計算機，更不用説能連接上世界的另一端的計算機了。如此，網絡使互聯網、雲、文件共享、媒體流、遠程管理、打印等服務成為可能。但是當網絡出現問題時，有時很難診斷到底是其中哪一環節出現了問題。下面，我們就來介紹：網絡連接最基本的診斷工具之一—— <code>ping</code> 命令。</p><h3 id="基本的-ping-命令" tabindex="-1">基本的 ping 命令 <a class="header-anchor" href="#基本的-ping-命令" aria-label="Permalink to “基本的 ping 命令”">​</a></h3><p>當你無法訪問本地網絡上的計算機或互聯網上的服務器時，你可以 <code>ping</code> 它的 IP 地址。<code>ping</code> 將 <ruby>互聯網控制報文協議<rt> Internet Control Message Protocol </rt></ruby>（ICMP）數據包發送到目標 IP 地址。當我們要對網路連接狀況進行判斷時，ICMP 是個非常有用的協議，本質上 ICMP 是一個響應和應答信號。</p><p>讓我們由近及遠地進行故障排除。請先 <code>ping</code> 你自己的計算機，以確保你的計算機正在運行 <ruby>網絡棧<rt> networking stack </rt></ruby>。你正在操作的計算機稱為 <ruby> 主機 <rt> localhost </rt></ruby>，本地迴環地址是：<code>127.0.0.1</code>。</p><p><code>ping</code> 命令能用主機的 <ruby>主機名<rt> hostname </rt></ruby>、IP 地址（即 <code>127.0.0.1</code>）或者僅僅用簡寫 <code>0</code> 來表示 “主機”。</p><p>你可以使用 <code>-c</code> 選項，來控制發送數據包的 <ruby>次數<rt> count </rt></ruby>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping 0 -c 1</span></span>
<span class="line"><span>PING 0 (127.0.0.1) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from 127.0.0.1: icmp_seq=1 ttl=64 time=0.069 ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--- 0 ping statistics ---</span></span>
<span class="line"><span>1 packets transmitted, 1 received, 0% packet loss, time 0ms</span></span>
<span class="line"><span>rtt min/avg/max/mdev = 0.069/0.069/0.069/0.000 ms</span></span></code></pre></div><p>在你確認本地網絡棧已啓動並運行後，接下來，你可以 <code>ping</code> 你的路由器的 IP 地址。路由器的 IP 地址通常以 <code>192.168</code> 或 <code>10</code> 開頭。實際的 IP 地址取決於路由器的配置。</p><p>當你沒有指定要發送多少次請求時，你可以用 <code>Ctrl+C</code>，來終止 <code>ping</code> 的運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping 192.168.0.1 </span></span>
<span class="line"><span>PING 192.168.0.1 (192.168.0.1) 56(84) bytes of data.</span></span>
<span class="line"><span>From 192.168.0.100: icmp_seq=2 Redirect Host(New nexthop: 192.168.0.1)</span></span>
<span class="line"><span>From 192.168.0.100: icmp_seq=3 Redirect Host(New nexthop: 192.168.0.1)</span></span>
<span class="line"><span>From 192.168.0.100: icmp_seq=4 Redirect Host(New nexthop: 192.168.0.1)</span></span>
<span class="line"><span>From 192.168.0.100: icmp_seq=5 Redirect Host(New nexthop: 192.168.0.1)</span></span>
<span class="line"><span>^C</span></span></code></pre></div><p>如果你能 <code>ping</code> 通路由器，則表示你的有線或無線連接能正常工作。</p><p>對於你的局域網上的其他主機呢？你可以 <code>ping</code> 各種設備，但是並非所有設備都能保證響應，因為一些設備會丟棄 ICMP 數據包，但許多設備會做出響應。例如，我可以 <code>ping</code> 我的打印機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping 192.168.0.4</span></span></code></pre></div><h3 id="ping-路由器以外的其他服務器" tabindex="-1">ping 路由器以外的其他服務器 <a class="header-anchor" href="#ping-路由器以外的其他服務器" aria-label="Permalink to “ping 路由器以外的其他服務器”">​</a></h3><p>在確定你自己的網絡內部都能連通以後，你還可以 <code>ping</code> 通到路由器以外的其他服務器。同樣地，並非所有服務器都能接收 ICMP 數據包，更不用説響應 ICMP 數據包了。然而，也有一些服務器可以接收並響應 ICMP 數據包，而在互聯網中的一個重要服務器是 <ruby>域名服務器<rt> nameserver </rt></ruby>。</p><p>谷歌的 <ruby>域名解析服務器<rt> DNS server </rt></ruby>的 IP 地址很容易記住，而且它會響應 <code>ping</code> 請求：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -c 2 8.8.8.8</span></span>
<span class="line"><span>PING 8.8.8.8 (8.8.8.8) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from 8.8.8.8: icmp_seq=1 ttl=116 time=53.3 ms</span></span>
<span class="line"><span>64 bytes from 8.8.8.8: icmp_seq=2 ttl=116 time=53.5 ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--- 8.8.8.8 ping statistics ---</span></span>
<span class="line"><span>2 packets transmitted, 2 received, 0% packet loss, time 1000ms</span></span>
<span class="line"><span>rtt min/avg/max/mdev = 53.304/53.424/53.544/0.120 ms</span></span></code></pre></div><p>當你連不上一個網站時，你可以查詢全球 DNS 網絡，以找出其主機服務器的地址，然後 <code>ping</code> 該服務器。這至少可以告訴你，網站不通的原因是主機已關閉，或者只是 Web 服務器問題。</p><p>例如，假設你嘗試訪問 <code>example.com</code>，但是發現失敗了。首先，使用 <code>host</code> 命令找到 <code>example.com</code> 的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ host example.com</span></span>
<span class="line"><span>example.com has address 93.184.216.34</span></span>
<span class="line"><span>example.com has IPv6 address 2606:2800:220:1:248:1893:25c8:1946</span></span>
<span class="line"><span>example.com mail is handled by 0</span></span></code></pre></div><p>然後，<code>ping</code> 該網站的的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping 93.184.216.34 -c 1</span></span></code></pre></div><h3 id="使用-ipv6" tabindex="-1">使用 IPv6 <a class="header-anchor" href="#使用-ipv6" aria-label="Permalink to “使用 IPv6”">​</a></h3><p><code>ping</code> 不僅可以使用 IPv4，還能使用 IPv6。可以通過指定 <code>-4</code> 或 <code>-6</code> 選項，來只使用 IPv4 或 IPv6。</p><h3 id="設置數據包大小" tabindex="-1">設置數據包大小 <a class="header-anchor" href="#設置數據包大小" aria-label="Permalink to “設置數據包大小”">​</a></h3><p>你可以使用 <code>-s</code> 選項，來更改要發送的 ICMP 數據包的 <ruby>大小<rt> size </rt></ruby>。默認的數據大小為 56 字節，加上 8 字節包頭，總共得到 64 字節的 ICMP 數據包。以下的示例將發送的 ICMP 數據包大小修改為 35+8=43 個字節：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -s 35 -c 5 8.8.8.8</span></span></code></pre></div><p>你可以使用 <code>-D</code> 選項，使得在終端中的每個 <code>ping</code> 回覆之前，先打印出當前的時間戳。該時間戳為 UNIX 時間戳，加上微秒：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -D 8.8.8.8 </span></span>
<span class="line"><span>PING 8.8.8.8 (8.8.8.8) 56(84) bytes of data.</span></span>
<span class="line"><span>[1634013430.297468] 64 bytes from 8.8.8.8: icmp_seq=1 ttl=116 time=53.3 ms</span></span>
<span class="line"><span>[1634013431.298738] 64 bytes from 8.8.8.8: icmp_seq=2 ttl=116 time=53.1 ms</span></span></code></pre></div><h3 id="設置時間間隔-長短" tabindex="-1">設置時間間隔/長短 <a class="header-anchor" href="#設置時間間隔-長短" aria-label="Permalink to “設置時間間隔/長短”">​</a></h3><p>你可以使用 <code>-i</code> 選項，來更改兩次 <code>ping</code> 請求之間的 <ruby>時間間隔<rt> interval </rt></ruby>。以下的示例將 <code>ping</code> 間隔更改為 2 秒：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -i 2</span></span></code></pre></div><p>你也可以使用 <code>-w</code> 選項，來在一段時間後終止 <code>ping</code>，單位為秒。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -w 6</span></span></code></pre></div><h3 id="ping-的變體" tabindex="-1">ping 的變體 <a class="header-anchor" href="#ping-的變體" aria-label="Permalink to “ping 的變體”">​</a></h3>`,38)),i("p",null,[s[2]||(s[2]=i("code",null,"ping",-1)),s[3]||(s[3]=n(" 有很多變體。例如，",-1)),s[4]||(s[4]=i("code",null,"iputils",-1)),s[5]||(s[5]=n(" 包提供了 ",-1)),s[6]||(s[6]=i("code",null,"ping",-1)),s[7]||(s[7]=n(" 命令；",-1)),a(e,{href:"https://opensource.com/article/21/8/what-busybox"},{default:t(()=>[...s[0]||(s[0]=[n("Busybox",-1)])]),_:1}),s[8]||(s[8]=n(" 也有",-1)),s[9]||(s[9]=i("code",null,"ping",-1)),s[10]||(s[10]=n(" 命令；BSD 也有；甚至還有一個圖形界面的 ",-1)),s[11]||(s[11]=i("code",null,"ping",-1)),s[12]||(s[12]=n("：",-1)),s[13]||(s[13]=i("code",null,"gping",-1)),s[14]||(s[14]=n("，它可用於 Linux、macOS 和 Windows。你可以在 ",-1)),a(e,{href:"https://github.com/orf/gping"},{default:t(()=>[...s[1]||(s[1]=[n("GitHub",-1)])]),_:1}),s[15]||(s[15]=n(" 上找到更多有關 ",-1)),s[16]||(s[16]=i("code",null,"gping",-1)),s[17]||(s[17]=n(" 的信息。",-1))]),s[34]||(s[34]=i("h3",{id:"一起來學習吧",tabindex:"-1"},[n("一起來學習吧 "),i("a",{class:"header-anchor",href:"#一起來學習吧","aria-label":"Permalink to “一起來學習吧”"},"​")],-1)),s[35]||(s[35]=i("p",null,[i("code",null,"ping"),n(" 命令很簡單，但它可以幫你診斷網絡連接問題。下次再遇到網絡連接問題時，讓 "),i("code",null,"ping"),n(" 命令成為你解決問題的第一個工具吧。")],-1)),s[36]||(s[36]=i("hr",null,null,-1)),i("p",null,[s[19]||(s[19]=n("via: ",-1)),a(e,{href:"https://opensource.com/article/21/10/linux-ping-command"},{default:t(()=>[...s[18]||(s[18]=[n("https://opensource.com/article/21/10/linux-ping-command",-1)])]),_:1})]),i("p",null,[s[24]||(s[24]=n("作者：",-1)),a(e,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[20]||(s[20]=[n("Seth Kenlon",-1)])]),_:1}),s[25]||(s[25]=n(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[21]||(s[21]=[n("lujun9972",-1)])]),_:1}),s[26]||(s[26]=n(" 譯者：",-1)),a(e,{href:"https://github.com/chai001125"},{default:t(()=>[...s[22]||(s[22]=[n("chai001125",-1)])]),_:1}),s[27]||(s[27]=n(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[23]||(s[23]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[30]||(s[30]=n("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[28]||(s[28]=[n("LCTT",-1)])]),_:1}),s[31]||(s[31]=n(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[29]||(s[29]=[n("Linux中國",-1)])]),_:1}),s[32]||(s[32]=n(" 榮譽推出",-1))])])}const C=p(g,[["render",c]]);export{x as __pageData,C as default};
